create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade, first_name text not null default '', middle_name text, last_name text not null default '', email text, date_of_birth date, branch text, college text, study_year smallint, avatar_url text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.posts(id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles(id) on delete cascade, content text not null, image_url text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.likes(id uuid primary key default gen_random_uuid(), post_id uuid not null references public.posts(id) on delete cascade, user_id uuid not null references public.profiles(id) on delete cascade, created_at timestamptz not null default now(), unique(post_id,user_id));
create table if not exists public.comments(id uuid primary key default gen_random_uuid(), post_id uuid not null references public.posts(id) on delete cascade, user_id uuid not null references public.profiles(id) on delete cascade, content text not null, created_at timestamptz not null default now());
create index if not exists posts_created_idx on public.posts(created_at desc); create index if not exists posts_user_idx on public.posts(user_id); create index if not exists comments_post_idx on public.comments(post_id,created_at); create index if not exists likes_post_idx on public.likes(post_id);
alter table public.profiles enable row level security; alter table public.posts enable row level security; alter table public.likes enable row level security; alter table public.comments enable row level security;
do $$ declare t text; pol text; begin for t,pol in select * from (values ('profiles','profiles_read'),('posts','posts_read'),('likes','likes_read'),('comments','comments_read')) as x(t,pol) loop execute format('drop policy if exists %I on public.%I',pol,t); execute format('create policy %I on public.%I for select to authenticated using (true)',pol,t); end loop; end $$;
drop policy if exists profiles_insert_self on public.profiles; create policy profiles_insert_self on public.profiles for insert to authenticated with check(id=auth.uid()); drop policy if exists profiles_update_self on public.profiles; create policy profiles_update_self on public.profiles for update to authenticated using(id=auth.uid()) with check(id=auth.uid());
drop policy if exists posts_insert_self on public.posts; create policy posts_insert_self on public.posts for insert to authenticated with check(user_id=auth.uid()); drop policy if exists posts_update_self on public.posts; create policy posts_update_self on public.posts for update to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid()); drop policy if exists posts_delete_self on public.posts; create policy posts_delete_self on public.posts for delete to authenticated using(user_id=auth.uid());
drop policy if exists likes_insert_self on public.likes; create policy likes_insert_self on public.likes for insert to authenticated with check(user_id=auth.uid()); drop policy if exists likes_delete_self on public.likes; create policy likes_delete_self on public.likes for delete to authenticated using(user_id=auth.uid());
drop policy if exists comments_insert_self on public.comments; create policy comments_insert_self on public.comments for insert to authenticated with check(user_id=auth.uid()); drop policy if exists comments_update_self on public.comments; create policy comments_update_self on public.comments for update to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid()); drop policy if exists comments_delete_self on public.comments; create policy comments_delete_self on public.comments for delete to authenticated using(user_id=auth.uid());
insert into storage.buckets(id,name,public) values ('profile-images','profile-images',true),('post-images','post-images',true) on conflict(id) do nothing;
